#!/usr/bin/env node
// thermo <celsius>      prints the temperature in Fahrenheit
// thermo -f <fahrenheit> prints the temperature in Celsius
const { cToF, fToC } = require('../conv.js');

const args = process.argv.slice(2);
if (args[0] === '-f') {
  const f = Number(args[1]);
  if (Number.isNaN(f)) { console.error('usage: thermo -f <fahrenheit>'); process.exit(2); }
  console.log(`${fToC(f)}°C`);
} else {
  const c = Number(args[0]);
  if (args.length === 0 || Number.isNaN(c)) { console.error('usage: thermo <celsius>'); process.exit(2); }
  console.log(`${cToF(c)}°F`);
}

#!/usr/bin/env node
// thermo-table [from] [to]  prints a Celsius to Fahrenheit table, one row per degree (default 30 to 40)
const { cToF } = require('../conv.js');

const from = Number(process.argv[2] ?? 30);
const to = Number(process.argv[3] ?? 40);
console.log('C\tF');
for (let c = from; c <= to; c++) console.log(`${c}\t${cToF(c)}`);

